WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.Score, p.CreationDate, u.DisplayName AS OwnerDisplayName, ROW_NUMBER() OVER (PARTITION BY p.PostTypeId ORDER BY p.Score DESC NULLS FIRST) AS PostRank FROM Posts AS p JOIN Users AS u ON p.OwnerUserId = u.Id WHERE p.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR AND p.Score > 10), PostComments AS (SELECT c.PostId, COUNT(c.Id) AS CommentCount, MAX(c.CreationDate) AS LastCommentDate FROM Comments AS c GROUP BY c.PostId), PostCloseReasons AS (SELECT ph.PostId, GROUP_CONCAT(crt.Name, ', ') AS CloseReasons FROM PostHistory AS ph JOIN CloseReasonTypes AS crt ON CAST(ph.Comment AS Nullable(Int32)) = crt.Id WHERE ph.PostHistoryTypeId IN (10, 11) GROUP BY ph.PostId) SELECT rp.PostId, rp.Title, rp.Score, rp.CreationDate, rp.OwnerDisplayName, COALESCE(pc.CommentCount, 0) AS CommentCount, pc.LastCommentDate, pcr.CloseReasons FROM RankedPosts AS rp LEFT JOIN PostComments AS pc ON rp.PostId = pc.PostId LEFT JOIN PostCloseReasons AS pcr ON rp.PostId = pcr.PostId WHERE rp.PostRank <= 5 ORDER BY rp.Score DESC NULLS FIRST, rp.CreationDate DESC NULLS FIRST